81	void ExchangeAddr(bool is_client, void *local_buf, uintptr_t &remote_addr, int &fd) {
82	  if (is_client) {
83	    fd = socket(AF_INET, SOCK_STREAM, 0);
84	    struct sockaddr_in addr {};
85	    addr.sin_family = AF_INET;
86	    addr.sin_port = htons(kSocketPort);
87	    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
88	    HixlExitOnFailure(connect(fd, reinterpret_cast<struct sockaddr *>(&addr), sizeof(addr)) == 0,
89	                      "socket connect failed");
90	    recv(fd, &remote_addr, sizeof(remote_addr), 0);
91	    printf("[INFO] Got remote addr: 0x%lx\n", remote_addr);
92	  } else {
93	    int lfd = socket(AF_INET, SOCK_STREAM, 0);
94	    int opt = 1;
95	    setsockopt(lfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
96	    struct sockaddr_in addr {};
97	    addr.sin_family = AF_INET;
98	    addr.sin_addr.s_addr = htonl(INADDR_ANY);
99	    addr.sin_port = htons(kSocketPort);
100	    bind(lfd, reinterpret_cast<struct sockaddr *>(&addr), sizeof(addr));
101	    listen(lfd, 1);
102	    printf("[INFO] Server waiting on port %d...\n", kSocketPort);
103	    fd = accept(lfd, nullptr, nullptr);
104	    close(lfd);
105	    uintptr_t local_addr = reinterpret_cast<uintptr_t>(local_buf);
106	    send(fd, &local_addr, sizeof(local_addr), 0);
107	    printf("[INFO] Sent local addr: %p\n", local_buf);
108	  }
