113	  ACL_EXIT_ON_FAILURE(aclrtMemcpy(host.data(), kBufSize, buf, kBufSize, ACL_MEMCPY_DEVICE_TO_HOST));
114	  std::vector<uint8_t> expected(kBufSize, kFillValue);
115	  bool ok = (memcmp(host.data(), expected.data(), kBufSize) == 0);
116	  HixlExitOnFailure(ok, "Verify failed");
117	  printf("[INFO] Verify success\n");
118	}
