140	void PrepareClientMemAndOp(EngineCtx &ctx) {
141	  ACL_EXIT_ON_FAILURE(aclrtMalloc(&ctx.buf, kBufSize, ACL_MEM_MALLOC_HUGE_ONLY));
142	  ctx.desc.addr = reinterpret_cast<uintptr_t>(ctx.buf);
143	  ctx.desc.len = kBufSize;
144	
145	  uintptr_t remote_addr = 0;
146	  ExchangeAddr(true, ctx.buf, remote_addr, ctx.fd);
147	
148	  ctx.op.local_addr = ctx.desc.addr;
149	  ctx.op.remote_addr = remote_addr;
150	  ctx.op.len = kBufSize;
151	}
