155	  ctx.device = kDeviceClient;
156	
157	  InitEngine(ctx, kClientEngine);
158	  PrepareClientMemAndOp(ctx);
159	  HixlExitOnFailure(ctx.engine.RegisterMem(ctx.desc, MEM_DEVICE, ctx.handle), "RegisterMem");
160	  printf("[INFO] RegisterMem success, buf=%p\n", ctx.buf);
161	
162	  HixlExitOnFailure(ctx.engine.Connect(kServerEngine, kTimeoutMs), "Connect");
163	  HixlExitOnFailure(ctx.engine.TransferSync(kServerEngine, READ, {ctx.op}, kTimeoutMs), "TransferSync");
164	  printf("[INFO] TransferSync READ completed\n");
165	  VerifyData(ctx.buf);
166	
167	  HixlExitOnFailure(send(ctx.fd, "d", 1, 0) == 1, "send done signal failed");
168	  HixlExitOnFailure(ctx.engine.Disconnect(kServerEngine, kTimeoutMs), "Disconnect");
169	  printf("[INFO] Disconnect done\n");
170	
171	  Finalize(ctx);
172	}
